import{_ as o,C as s,o as n,c as i,j as e,a,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const p="/videos/picker-replay-loop.mp4",b=JSON.parse(`{"title":"Replay a recording","description":"Play a recording or a bug report's steps again in a tab with Piwi Picker, with a cursor and a caption per step, and see whether the bug shows on your own dev server, or run them with Playwright in the desktop app.","frontmatter":{"title":"Replay a recording","description":"Play a recording or a bug report's steps again in a tab with Piwi Picker, with a cursor and a caption per step, and see whether the bug shows on your own dev server, or run them with Playwright in the desktop app.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/replay-a-bug-report.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/replay-a-bug-report.html"}],["meta",{"property":"og:title","content":"Replay a recording | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Play a recording or a bug report's steps again in a tab with Piwi Picker, with a cursor and a caption per step, and see whether the bug shows on your own dev server, or run them with Playwright in the desktop app."}]]},"headers":[],"relativePath":"features/replay-a-bug-report.md","filePath":"features/replay-a-bug-report.md","lastUpdated":1795855133000}`),l={name:"features/replay-a-bug-report.md"};function c(g,t,u,w,y,f){const r=s("Needs");return n(),i("div",null,[t[0]||(t[0]=e("h1",{id:"replay-a-recording",tabindex:"-1"},[a("Replay a recording "),e("a",{class:"header-anchor",href:"#replay-a-recording","aria-label":'Permalink to "Replay a recording"'},"​")],-1)),h(r,{extension:""}),t[1]||(t[1]=e("p",null,[e("strong",null,"Replay"),a(" plays a "),e("a",{href:"./record-actions.html"},"recording"),a("'s steps again in a tab, with a cursor that moves to each element and a caption saying what it does, then says whether each still finds its element and, for a "),e("a",{href:"./report-a-bug.html"},"bug report"),a(", whether the bug shows there. It suits the developer who receives a report: open the app on your own dev server, and the steps run there, with your session and your browser's developer tools at hand, or "),e("a",{href:"#running-it-with-playwright"},"with Playwright"),a(" in the desktop app.")],-1)),t[2]||(t[2]=e("figure",null,[e("video",{src:p,autoplay:"",loop:"",muted:"",playsinline:"",controls:"","aria-label":"Replaying a bug report on a cart page: the cursor fills the coupon, clicks Apply and checks the total, and the verdict says the bug shows here, the total reading 50 instead of 45"}),e("figcaption",null,"The report's four steps played again, then the verdict: reproduced.")],-1)),t[3]||(t[3]=d('<h2 id="choosing-a-recording" tabindex="-1">Choosing a recording <a class="header-anchor" href="#choosing-a-recording" aria-label="Permalink to &quot;Choosing a recording&quot;">​</a></h2><ul><li>From a recording&#39;s <a href="./record-actions.html#the-finish-panel">finish panel</a>, <strong>Replay</strong> plays it at once on the same site.</li><li>From the popup, <strong>Replay</strong> (<code>R</code>) asks for the site&#39;s access if needed, then for what to play: the recording just made in this browser, a bug report or not, a <a href="/reference/bug-report-file.html"><code>.piwibug</code> file</a> (or the same file named <code>.zip</code>) or its <code>steps.json</code>, the text of a <code>steps.json</code> pasted in, or, connected, one of the project&#39;s reports on Piwi.</li><li>From a failed execution on the dashboard, <strong>Export → Bug report (.piwibug)</strong> makes a report from the test run (<a href="#a-report-made-from-a-test-run">below</a>), and <strong>Steps (steps.json)</strong> copies its steps to paste.</li></ul><p>The steps run on the tab&#39;s site, whichever site they were recorded on. A step that opens its page in a new tab, such as a link that opens an order beside the list, takes the replay to that tab, as the recording went on there.</p><h2 id="the-answer" tabindex="-1">The answer <a class="header-anchor" href="#the-answer" aria-label="Permalink to &quot;The answer&quot;">​</a></h2><p>Each element is looked for with every locator it was recorded with, the one the test uses first. When that one finds nothing for two seconds, finds several elements, or finds one the other locators disagree on, the element most of them agree on is used, and the step says which locator found it: a label that changed or an id made up on each load does not stop the replay. The element is then waited for as Playwright waits: visible, enabled and still, for as long as Playwright waits or, when you waited longer for it while recording (a reply that takes the server fifteen seconds), that long and a few seconds more, up to a minute. The replay ends with one of five answers:</p><ul><li><strong>Reproduced</strong>: a step marked wrong, or a recording&#39;s check, does not hold, such as a total that still reads &quot;Total: 40.00&quot;, and the panel says whether that is the value reported.</li><li><strong>Not reproduced</strong>: every expected result holds here.</li><li><strong>Could not reach the bug</strong> (the dashboard&#39;s <em>diverged</em>): a step could not be played (it found no element, several, or a disabled one, or the flow ended on another page) and you stopped there, or a check that held when recorded fails. The data, the login or a flag differ here.</li><li><strong>Failed at step 4, as in the test run</strong>: in a report made from a test run, the step that could not be played is the one the test failed at.</li><li><strong>Replayed every step</strong>: the steps hold no check.</li></ul><p>A recording that marks nothing wrong says <strong>A check failed</strong>, <strong>Every check holds</strong> or <strong>Stopped at step 4: the page went another way</strong> for the first three.</p><p>Under the answer, the panel lists the failed requests and console errors the page showed during the replay, such as &quot;POST /api/cart/coupon answered 500&quot;: from the moment the replay started, never those of the recording, even when you replay on the page you just recorded the report on. For a report from Piwi, <strong>Share result…</strong> records the answer on the report, with the site it ran on, after showing what it sends.</p><p><strong>Step by step</strong> waits for <strong>Next</strong> before each step, with the element outlined, so you can set a breakpoint first.</p><h2 id="when-a-step-cannot-be-played" tabindex="-1">When a step cannot be played <a class="header-anchor" href="#when-a-step-cannot-be-played" aria-label="Permalink to &quot;When a step cannot be played&quot;">​</a></h2><p>A step Replay cannot play is handed to you rather than ending the replay. The panel says why, names the step in words and, when the report has <a href="./report-a-bug.html#evidence">a screenshot of each step</a>, shows the page as it began there, the element outlined. It lists the locators the element was recorded with and outlines on the page every element they still find, such as two buttons where the recording saw one, as the page changes. Do it yourself on the page, then choose:</p><ul><li><strong>I did it, continue</strong>: the replay goes on with the next step, even when your action loaded another page or opened one in a new tab.</li><li><strong>Skip this step</strong>: it goes on without it.</li><li><strong>Stop here</strong>: it ends there, and says it could not reach the bug.</li></ul><p>A password, or a card number, its security code or a one-time code, is never in a report, nor what was typed when the sender left the typed values out: Replay hands that step to you to type it. A click or a key the page never got is handed to you too: a browser dialog in front of the tab, such as Chrome&#39;s warning about a password found in a data breach after a login, takes the input. Close it, then do the step. A hover recorded without any locator is skipped, since the next step points at its own element.</p><p>Under the answer, the panel lists the steps played by hand.</p><h2 id="a-report-made-from-a-test-run" tabindex="-1">A report made from a test run <a class="header-anchor" href="#a-report-made-from-a-test-run" aria-label="Permalink to &quot;A report made from a test run&quot;">​</a></h2><p>A <code>.piwibug</code> exported from a failed execution holds the test&#39;s steps up to the failure and its failing assertion; what the run did not keep enough of to play becomes a <a href="/reference/steps-format.html#manual-steps">manual step</a>, which Replay hands to you as above, with the line of the test it stands for, in Piwi Picker&#39;s language. Calls that are not steps at all are listed in the report&#39;s Markdown under <strong>Not replayed</strong>.</p><p>When the test failed on an action rather than on an assertion, the report says which step; reaching it and failing there answers <strong>Failed at step N, as in the test run</strong>, and playing it answers <strong>Not reproduced</strong>.</p><p>A test run does not keep the page each step happened on once a click may have opened another, so Replay does not follow such a step into a new tab: it stays in the tab it started in, and a step the test played in a popup is handed to you.</p><h2 id="trusted-input" tabindex="-1">Trusted input <a class="header-anchor" href="#trusted-input" aria-label="Permalink to &quot;Trusted input&quot;">​</a></h2><p>In Chrome and Edge, Replay sends trusted input as Playwright does, through the <a href="./extension.html#the-debugging-bar">debugging protocol</a>: a real hover, clicks, keys and drags that the page cannot tell from a person&#39;s, under Chrome&#39;s debugging bar until the replay ends. In Firefox, when the browser refuses the session, once the bar is cancelled, or once the browser refuses one of its commands (the bar then closes), Replay goes on with the page&#39;s own events; the panel says which, step by step.</p><p>A report names the files a step chose but never carries them: Replay asks you to choose them, or to skip the step.</p><p>With trusted input, each step plays at the viewport size it was recorded at, in CSS pixels whatever your zoom, and the tab gets its own size back when the replay ends. Otherwise the panel says when the window&#39;s size differs from the recorded one, so you can resize it.</p><h2 id="running-it-with-playwright" tabindex="-1">Running it with Playwright <a class="header-anchor" href="#running-it-with-playwright" aria-label="Permalink to &quot;Running it with Playwright&quot;">​</a></h2><p>For the exact verdict and a trace, the <a href="./desktop.html">desktop app</a> runs a report&#39;s steps with Playwright in your project, once Piwi Picker is <a href="./extension-connection.html#pair-with-the-desktop-app">paired with it</a>. <strong>Run with Playwright…</strong>, in Replay&#39;s chooser beside <strong>Start</strong> or on a finished replay, shows what it sends (the title and the steps, with the values typed in them) and sends it on <strong>Send</strong>. The request holds steps, never code. The app&#39;s window shows it with the steps in words, the linked project to run it in, and the flags (headed and a trace by default, a Playwright project, a repeat count). Nothing runs before <strong>Run with Playwright</strong>; <strong>Decline</strong> drops it, and a request left unanswered expires after ten minutes.</p><p>The app writes the spec to run, with the project&#39;s settings, to <code>piwi-repro/bug-&lt;id&gt;.spec.ts</code> under the test directory your Playwright config names, runs it in the <strong>Local runs</strong> tray with the project&#39;s own config, and deletes it when the run ends. The verdict, read from where the test failed, goes back to Piwi Picker: <strong>reproduced</strong> when an expected result does not hold, <strong>not reproduced</strong> when the test passes, or <strong>diverged</strong> at the step that failed first.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li>It plays one site, in the top-level document only, as the recording was made. A step that opens another site, or an address that is not a web page, is handed to you.</li><li><strong>Share result…</strong> and <strong>Run with Playwright…</strong> are the only parts that send anything, each after showing what it sends.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./record-actions.html">Record a test</a>: the recording Replay plays</li><li><a href="./report-a-bug.html">Record a bug report</a>: marking what the page gets wrong</li><li><a href="./bug-reports.html">Bug reports on your instance</a>: the reports kept</li><li><a href="/reference/bug-report-file.html">Bug report file format</a>: what a <code>.piwibug</code> holds</li></ul>',29))])}const k=o(l,[["render",c]]);export{b as __pageData,k as default};
